settings.custom_liquid:
{% assign rating_val = product.metafields.custom.rating_avg.value %}
{% assign sold_val = product.metafields.custom.sold_text.value %}

{% if rating_val != blank or sold_val != blank %}
<div class="edc-rb">
  {% if rating_val != blank %}
  <div class="edc-rb__left">
    <span class="edc-rb__stars">★★★★★</span>
    <span class="edc-rb__rating">{{ rating_val }}</span>
    <span class="edc-rb__sep">|</span>
  </div>
  {% endif %}

  {% if sold_val != blank %}
  <div class="edc-rb__badge">
    {{ sold_val }} vendidos
  </div>
  {% endif %}
</div>
{% endif %}

<style>
.edc-rb{
  display:flex;
  align-items:baseline;
  gap:10px;
  flex-wrap:nowrap;
  margin:8px 0 12px;
  white-space:nowrap;
}
.edc-rb__left{
  display:flex;
  align-items:baseline;
  gap:6px;
}
.edc-rb__stars{
  font-size:14px;
  letter-spacing:1px;
}
.edc-rb__rating{
  font-size:14px;
  font-weight:500;
}
.edc-rb__sep{
  opacity:.5;
}
.edc-rb__badge{
  font-size:13px;
  padding:5px 10px;
  border-radius:999px;
  line-height:1;
  background: linear-gradient(135deg, #e9e1ff 0%, #cfc2ff 100%);
  color:#2b2b2b;
  flex-shrink:0;
}
</style>

{%- assign v = product.selected_or_first_available_variant -%}

<div class="meli-cuotas">
  Mismo precio en 
  <strong>3 cuotas sin<br> interés de:</strong>
  <span class="meli-cuotas__amount">
    {{ v.price | divided_by: 3 | money }}
  </span>
</div>

<style>
.meli-cuotas{
  color:#00a650;
  font-size:13px;
  line-height:1.25;
  margin-top:4px;
}

.meli-cuotas strong{
  font-weight:600;
}

.meli-cuotas__amount{
  font-size:14px;
  font-weight:700;
  letter-spacing:.2px;
}
</style>

{%- comment -%}
  ML-style Payment Methods Popup (Shrine)
  - 3 cuotas sin interés (Mercado Pago)
  - Sin calculadora
  - Estilo: header amarillo + acordeones
{%- endcomment -%}

<!-- TRIGGER -->
<button
  type="button"
  class="mlpay-link"
  data-mlpay-open>
  Ver medios de pago
  <span class="mlpay-link-arrow" aria-hidden="true">›</span>
</button>

<div class="mlpay-backdrop" data-mlpay-backdrop hidden></div>

<div class="mlpay-modal"
     role="dialog"
     aria-modal="true"
     aria-labelledby="mlpayTitle"
     data-mlpay-modal
     hidden>

  <div class="mlpay-header">
    <button class="mlpay-back"
            type="button"
            aria-label="Volver"
            data-mlpay-close>
      ‹
    </button>
    <div class="mlpay-title" id="mlpayTitle">
      Medios de pago para este producto
    </div>
  </div>

  <div class="mlpay-body">

    <!-- INTRO -->
    <div class="mlpay-intro">
      Al finalizar tu compra, pagás con el dinero disponible en tu cuenta.
      Podés ingresar dinero a Mercado Pago por cuentas vinculadas,
      transferencia bancaria o en efectivo.

      <div class="mlpay-sub">Acreditación instantánea.</div>

      <a class="mlpay-more"
         href="https://www.mercadopago.com.ar/banking/balance"
         target="_blank"
         rel="noopener">
        Conocer más
      </a>
    </div>

    <div class="mlpay-accordion">

      <!-- TARJETAS DE CRÉDITO -->
      <details class="mlpay-item" open>
        <summary>
          <span class="mlpay-sum-title">Tarjetas de crédito</span>
          <span class="mlpay-chevron">▾</span>
        </summary>

        <div class="mlpay-content">
          <div class="mlpay-badge">
            Mismo precio en hasta 3 cuotas
          </div>

          {%- assign credit_logos = "visa|Visa,mastercard|Mastercard,american-express|American Express,cabal|Cabal,argencard|Argencard,diners-club|Diners Club,naranjax|Naranja X,tarjeta-shopping|Tarjeta Shopping" | split: "," -%}

          <div class="mlpay-logos">
            {%- for item in credit_logos -%}
              {%- assign parts = item | split: "|" -%}
              {%- assign handle = parts[0] -%}
              {%- assign label = parts[1] -%}
              <div class="mlpay-logo">
                <img
                  src="{{ 'bank-' | append: handle | append: '.svg' | file_url }}"
                  alt="{{ label }}"
                  class="mlpay-bank-icon"
                  loading="lazy">
              </div>
            {%- endfor -%}
          </div>

          <a class="mlpay-more"
             href="https://www.mercadolibre.com.ar/payments-methods?view=conditions"
             target="_blank"
             rel="noopener">
            Conocer condiciones
          </a>
        </div>
      </details>

      <!-- CUOTAS SIN TARJETA -->
      <details class="mlpay-item">
        <summary>
          <span class="mlpay-sum-title">Cuotas sin Tarjeta</span>
          <span class="mlpay-chevron">▾</span>
        </summary>

        <div class="mlpay-content">
          <p class="mlpay-p">
            Comprás y luego pagás las cuotas mes a mes con efectivo,
            débito o con el dinero de tu cuenta de Mercado Pago.
          </p>
          <div class="mlpay-sub">Acreditación instantánea.</div>

          <a class="mlpay-more"
             href="https://www.mercadolibre.com.ar/credits/consumer/enrollment/"
             target="_blank"
             rel="noopener">
            Conocer más
          </a>
        </div>
      </details>

      <!-- DINERO EN CUENTA -->
      <details class="mlpay-item">
        <summary>
          <span class="mlpay-sum-title">Dinero disponible en Mercado Pago</span>
          <span class="mlpay-chevron">▾</span>
        </summary>

        <div class="mlpay-content">
          <p class="mlpay-p">
            Pagás con el dinero disponible en tu cuenta de Mercado Pago.
          </p>
          <div class="mlpay-sub">Acreditación instantánea.</div>

          <a class="mlpay-more"
             href="https://www.mercadopago.com.ar/banking/balance"
             target="_blank"
             rel="noopener">
            Conocer más
          </a>
        </div>
      </details>

      <!-- DÉBITO -->
      <details class="mlpay-item">
        <summary>
          <span class="mlpay-sum-title">Tarjetas de débito</span>
          <span class="mlpay-chevron">▾</span>
        </summary>

        <div class="mlpay-content">
          <div class="mlpay-logos-row">
            <img src="{{ 'bank-visa-debit.svg' | file_url }}" class="mlpay-bank-icon">
            <img src="{{ 'bank-mastercard-debit.svg' | file_url }}" class="mlpay-bank-icon">
            <img src="{{ 'bank-cabal-debit.svg' | file_url }}" class="mlpay-bank-icon">
            <img src="{{ 'bank-maestro.svg' | file_url }}" class="mlpay-bank-icon">
          </div>
          <div class="mlpay-sub">Acreditación instantánea.</div>
        </div>
      </details>

      <!-- EFECTIVO -->
      <details class="mlpay-item">
        <summary>
          <span class="mlpay-sum-title">Efectivo</span>
          <span class="mlpay-chevron">▾</span>
        </summary>

        <div class="mlpay-content">
          <div class="mlpay-logos-row">
            <img src="{{ 'bank-pago-facil.svg' | file_url }}" class="mlpay-bank-icon">
            <img src="{{ 'bank-rapipago.svg' | file_url }}" class="mlpay-bank-icon">
          </div>
          <div class="mlpay-sub">Acreditación instantánea.</div>
        </div>
      </details>

    </div>
  </div>
</div>

<style>
[hidden]{display:none!important}

.mlpay-link{
  background:none;
  border:0;
  padding:0;
  display:inline-flex;
  gap:6px;
  font-size:14px;
  font-weight:500;
  color:#3483FA;
  cursor:pointer;
}
.mlpay-link:hover{text-decoration:underline}

.mlpay-backdrop{
  position:fixed;
  inset:0;
  background:rgba(0,0,0,.45);
  z-index:9998;
}

.mlpay-modal{
  position:fixed;
  inset:0;
  max-width:520px;
  margin:auto;
  background:#fff;
  z-index:9999;
  display:flex;
  flex-direction:column;
}

.mlpay-header{
  background:#F9D500;
  padding:12px;
  display:flex;
  align-items:center;
  gap:10px;
}

.mlpay-back{
  background:none;
  border:0;
  font-size:28px;
  cursor:pointer;
}

.mlpay-title{
  font-weight:700;
  font-size:16px;
  line-height:1.15;
}

.mlpay-body{padding:16px;overflow:auto}

.mlpay-item summary{
  display:flex;
  justify-content:space-between;
  cursor:pointer;
  padding:10px 0;
}

.mlpay-chevron{color:#777}

.mlpay-content{padding-bottom:14px}

.mlpay-badge{
  background:#EAF7EA;
  color:#1C7C3A;
  font-size:12px;
  font-weight:700;
  padding:6px 10px;
  border-radius:999px;
  display:inline-block;
  margin-bottom:10px;
}

.mlpay-logos{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:12px;
}

.mlpay-logo{
  background:#fafafa;
  border-radius:12px;
  padding:12px;
  display:flex;
  justify-content:center;
}

.mlpay-bank-icon{
  width:90px;
  height:28px;
  object-fit:contain;
}

.mlpay-more{
  color:#2D6CDF;
  font-weight:600;
  font-size:13px;
  text-decoration:none;
}

.mlpay-more:hover{text-decoration:underline}
</style>

<script>
(function(){
  const openBtn=document.querySelector('[data-mlpay-open]');
  const modal=document.querySelector('[data-mlpay-modal]');
  const closeBtn=document.querySelector('[data-mlpay-close]');
  const backdrop=document.querySelector('[data-mlpay-backdrop]');
  if(!openBtn||!modal||!closeBtn||!backdrop)return;

  function openModal(){
    modal.hidden=false;
    backdrop.hidden=false;
    document.documentElement.style.overflow='hidden';
  }

  function closeModal(){
    modal.hidden=true;
    backdrop.hidden=true;
    document.documentElement.style.overflow='';
  }

  openBtn.addEventListener('click',openModal);
  closeBtn.addEventListener('click',closeModal);
  backdrop.addEventListener('click',closeModal);
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape'&&!modal.hidden)closeModal();
  });
})();
</script>
